import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"My Wallet – Voucher","description":"","frontmatter":{"title":"My Wallet – Voucher"},"headers":[],"relativePath":"operations-knowledge-base/presales-support/my-wallet-voucher.md","filePath":"operations-knowledge-base/presales-support/my-wallet-voucher.md","lastUpdated":1794292919000}'),o={name:"operations-knowledge-base/presales-support/my-wallet-voucher.md"};function s(n,e,l,u,c,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h2 id="_1-feature-overview" tabindex="-1">1. Feature Overview <a class="header-anchor" href="#_1-feature-overview" aria-label="Permalink to &quot;1. Feature Overview&quot;">​</a></h2><p>Vouchers are discount credits provided by the platform that can be used to deduct a certain amount from eligible product purchases, helping users reduce service costs.</p><p>The “Voucher” page under the billing module allows users to view, filter, and use vouchers.</p><h2 id="_2-access-path" tabindex="-1">2. Access Path <a class="header-anchor" href="#_2-access-path" aria-label="Permalink to &quot;2. Access Path&quot;">​</a></h2><p>Navigate to Customer Center → Billing → My Wallet, then click the “Voucher” tab at the top of the page to enter the voucher management interface.</p><h2 id="_3-feature-description" tabindex="-1">3. Feature Description <a class="header-anchor" href="#_3-feature-description" aria-label="Permalink to &quot;3. Feature Description&quot;">​</a></h2><h3 id="_1-filtering-and-settings" tabindex="-1">(1) Filtering and Settings <a class="header-anchor" href="#_1-filtering-and-settings" aria-label="Permalink to &quot;(1) Filtering and Settings&quot;">​</a></h3><h4 id="status-filter" tabindex="-1">Status Filter <a class="header-anchor" href="#status-filter" aria-label="Permalink to &quot;Status Filter&quot;">​</a></h4><p>Use the “Status” dropdown menu to filter vouchers by status, including:</p><ul><li>All Status</li><li>Unused</li><li>Expired</li><li>Used</li><li>Inactive</li></ul><h4 id="applicable-product-filter" tabindex="-1">Applicable Product Filter <a class="header-anchor" href="#applicable-product-filter" aria-label="Permalink to &quot;Applicable Product Filter&quot;">​</a></h4><p>Use the “Applicable Product” dropdown menu to filter vouchers by supported product type, such as:</p><ul><li>All Products</li><li>VPS</li><li>Cloud Server</li><li>Dedicated Servers</li></ul><h4 id="save-filter-configuration" tabindex="-1">Save Filter Configuration <a class="header-anchor" href="#save-filter-configuration" aria-label="Permalink to &quot;Save Filter Configuration&quot;">​</a></h4><p>After selecting the desired filters, click “Save Current Configuration” to save the selected conditions for easier access to the same voucher list later.</p><h3 id="_2-voucher-list-information" tabindex="-1">(2) Voucher List Information <a class="header-anchor" href="#_2-voucher-list-information" aria-label="Permalink to &quot;(2) Voucher List Information&quot;">​</a></h3><p>The voucher list displays the following key information:</p><p><strong>Name</strong> The promotion name or voucher identifier (e.g., “Holiday Prepaid Bonus Credit”).</p><p><strong>Amount</strong> The amount that can be deducted when using the voucher.</p><p><strong>Status</strong> The current usage status of the voucher (e.g., Unused).</p><p><strong>Effective Date / Expiration Date</strong> The valid time range during which the voucher can be used. Vouchers must be used within the validity period.</p><p><strong>Operation</strong></p><ul><li><strong>Use Now</strong> - Redirects to the corresponding product purchase or renewal page where the voucher can be applied.</li><li><strong>Transaction Records</strong> - View detailed records related to the voucher, such as issuance and usage history.</li></ul><h3 id="_3-pagination" tabindex="-1">(3) Pagination <a class="header-anchor" href="#_3-pagination" aria-label="Permalink to &quot;(3) Pagination&quot;">​</a></h3><p>The bottom of the page supports pagination for viewing additional voucher records.</p><p>Users can switch pages using the “Previous Page” and “Next Page” buttons.</p>',26)])])}const g=t(o,[["render",s]]);export{p as __pageData,g as default};
